                    "sql": "DELETE FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_receiving_details` WHERE source_airbyte_emitted_at_date >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY); INSERT INTO `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_receiving_details` WITH staged_receivings AS ( SELECT SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.id\') AS INT64) AS id, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.warehouse\') AS warehouse, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.receiving_key\') AS receiving_key, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.asn\') AS asn, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.bol_number\') AS bol_number, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.supplier_name\') AS supplier_name, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.handling_unit_type\') AS handling_unit_type, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.handling_unit_quantity\') AS INT64) AS handling_unit_quantity, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.estimated_delivery\') AS estimated_delivery, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.description\') AS description, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.status\') AS status, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.created_at\') ) AS created_at, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.updated_at\') ) AS updated_at, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.arrived_at\') ) AS arrived_at, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.received_at\') ) AS received_at, ARRAY( SELECT AS STRUCT STRUCT( SAFE_CAST(JSON_VALUE(item, \'$.product.id\') AS INT64) AS id, JSON_VALUE(item, \'$.product.sku\') AS sku, JSON_VALUE(item, \'$.product.name\') AS name ) AS product, SAFE_CAST(JSON_VALUE(item, \'$.expected_quantity\') AS INT64) AS expected_quantity, SAFE_CAST(JSON_VALUE(item, \'$.received_quantity\') AS INT64) AS received_quantity, ARRAY( SELECT AS STRUCT STRUCT( JSON_VALUE(receiving_detail, \'$.lot.lot_number\') AS lot_number, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(receiving_detail, \'$.lot.expiration_date\') ) AS expiration_date ) AS lot, SAFE_CAST(JSON_VALUE(receiving_detail, \'$.expected_quantity\') AS INT64) AS expected_quantity, SAFE_CAST(JSON_VALUE(receiving_detail, \'$.received_quantity\') AS INT64) AS received_quantity, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(receiving_detail, \'$.received_at\') ) AS received_at, JSON_VALUE(receiving_detail, \'$.line_key\') AS line_key FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(item, \'$.receiving_details\'), [])) AS receiving_detail ) AS receiving_details FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.items\'), [])) AS item ) AS items, ARRAY( SELECT AS STRUCT JSON_VALUE(receiving_line, \'$.line_key\') AS line_key, STRUCT( SAFE_CAST(JSON_VALUE(receiving_line, \'$.product.id\') AS INT64) AS id, JSON_VALUE(receiving_line, \'$.product.sku\') AS sku, JSON_VALUE(receiving_line, \'$.product.name\') AS name ) AS product, SAFE_CAST(JSON_VALUE(receiving_line, \'$.expected_quantity\') AS INT64) AS expected_quantity, SAFE_CAST(JSON_VALUE(receiving_line, \'$.received_quantity\') AS INT64) AS received_quantity, JSON_VALUE(receiving_line, \'$.sscc\') AS sscc, JSON_VALUE(receiving_line, \'$.carton_key\') AS carton_key, JSON_VALUE(receiving_line, \'$.loose_units_pallet_key\') AS loose_units_pallet_key, STRUCT( JSON_VALUE(receiving_line, \'$.lot.lot_number\') AS lot_number, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(receiving_line, \'$.lot.expiration_date\') ) AS expiration_date ) AS lot FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.receiving_lines\'), [])) AS receiving_line ) AS receiving_lines, ARRAY( SELECT AS STRUCT JSON_VALUE(custom_field, \'$.name\') AS name, JSON_QUERY(custom_field, \'$.value\') AS value FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.custom_data\'), [])) AS custom_field ) AS custom_data, ARRAY( SELECT AS STRUCT JSON_VALUE(carton, \'$.carton_key\') AS carton_key, JSON_VALUE(carton, \'$.pallet_key\') AS pallet_key, ARRAY( SELECT AS STRUCT JSON_VALUE(identifier, \'$.type\') AS type, JSON_VALUE(identifier, \'$.value\') AS value FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(carton, \'$.identifiers\'), [])) AS identifier ) AS identifiers FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.cartons\'), [])) AS carton ) AS cartons, ARRAY( SELECT AS STRUCT JSON_VALUE(pallet, \'$.pallet_key\') AS pallet_key, ARRAY( SELECT AS STRUCT JSON_VALUE(identifier, \'$.type\') AS type, JSON_VALUE(identifier, \'$.value\') AS value FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(pallet, \'$.identifiers\'), [])) AS identifier ) AS identifiers FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.pallets\'), [])) AS pallet ) AS pallets, SAFE.PARSE_JSON(data) AS raw_data, _airbyte_unique_key AS source_airbyte_unique_key, _airbyte_ab_id AS source_airbyte_ab_id, _airbyte_emitted_at AS source_airbyte_emitted_at, DATE(_airbyte_emitted_at, \'Asia/Kolkata\') AS source_airbyte_emitted_at_date, _airbyte_normalized_at AS source_airbyte_normalized_at, _airbyte_shipmonk_get_list_of_receivings_hashid AS source_airbyte_hashid, CURRENT_TIMESTAMP() AS bq_load_ts FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_get_list_of_receivings` WHERE DATE(_airbyte_emitted_at, \'Asia/Kolkata\') >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY) ) SELECT * FROM staged_receivings;",
                    "transaction": true
                }
